+                calls.installed.push(port);
+                0
+            }
+        })
+    }
+
+    unsafe extern "C" fn deallocate(_: mach_port_t, port: mach_port_t) -> c_int {
+        CALLS.with(|calls| calls.borrow_mut().released.push(port));
