diff --git a/crates/infra/daemon/tests/g6_e2e.rs b/crates/infra/daemon/tests/g6_e2e.rs
new file mode 100644
index 0000000..7bc327a
--- /dev/null
+++ b/crates/infra/daemon/tests/g6_e2e.rs
@@ -0,0 +1,350 @@
+//! G6 e2e — the real daemon path, not the shadow path.
+//!
+//! `orbit_container.rs` rebuilds `Daemon::orbit_setup`'s resolution logic in
+//! the test itself ("performs in production" — its own words) and hands the
+//! result to a `Worker` directly. That skips exactly the pieces G6 wired:
+//! `Daemon::start` -> `assemble_plugins` -> `orbit_setup` -> real worker ->
+//! real orbit loop -> `HttpLlm` -> an actual HTTP call.
+//!
+//! These tests close that gap. A daemon is started for real on a temp socket
+//! with `orbit_model` pointing at a local mock OpenAI server, so the request
+//! the loop makes leaves the process, hits a socket we control, and the reply
+//! travels back through the real SSE/HTTP decode path. What is asserted is
+//! what only the full chain can prove:
+//!
+//! 1. `AGENTS.md` in the workspace the daemon was configured with reaches the
+//!    HTTP body the backend actually received — end to end, not a recorded
+//!    `Context` from a scripted backend swapped in at construction.
+//! 2. `[daemon] max_turns` in the config document caps the real run: the mock
+//!    never ends a turn on its own, so the only thing that can stop the loop
+//!    is the cap flowing document -> assemble -> resolve -> worker -> loop.
+//! 3. A daemon killed mid-run, restarted on the same DB, closes the orphan.
+
+use std::io::{Read, Write};
+use std::net::{TcpListener, TcpStream};
+use std::sync::{Arc, Mutex};
+use std::thread;
+use std::time::Duration;
+
+use daemon::protocol::Command;
+use daemon::{Daemon, DaemonClient, DaemonConfig, EventFrame, Subscription};
+use serde_json::{Value, json};
+use tempfile::tempdir;
+
+/// Distinctive token written into the workspace `AGENTS.md`. If instruction
+/// injection works end to end, this string is inside the HTTP request body
+/// the mock server received.
+const MARKER: &str = "G6-E2E-INSTRUCTION-MARKER";
+
+const EVENT_TIMEOUT: Duration = Duration::from_secs(10);
+
+/// A tiny OpenAI-compatible server: one thread per connection, replays the
+/// canned SSE stream for every `/chat/completions` POST, and records the raw
+/// request bodies so the test can assert on what the loop really sent.
+struct MockOpenAi {
+    addr: String,
+    bodies: Arc<Mutex<Vec<String>>>,
+}
+
+impl MockOpenAi {
+    fn start(replies: Vec<String>) -> Self {
+        let listener = TcpListener::bind("127.0.0.1:0").expect("bind mock");
+        let addr = listener.local_addr().expect("local addr");
+        let bodies = Arc::new(Mutex::new(Vec::new()));
+        let bodies_srv = Arc::clone(&bodies);
+        let replies_srv = replies.clone();
+
+        thread::spawn(move || {
+            for stream in listener.incoming() {
+                let Ok(stream) = stream else { break };
+                let bodies = Arc::clone(&bodies_srv);
+                let replies = replies_srv.clone();
+                thread::spawn(move || serve(stream, bodies, replies));
+            }
+        });
+
+        MockOpenAi {
+            addr: format!("http://127.0.0.1:{}", addr.port()),
+            bodies,
+        }
+    }
+
+    /// Bodies of every `/chat/completions` POST, in arrival order.
+    fn received(&self) -> Vec<String> {
+        self.bodies.lock().expect("bodies").clone()
+    }
+}
+
+fn serve(stream: TcpStream, bodies: Arc<Mutex<Vec<String>>>, replies: Vec<String>) {
+    let mut stream = stream;
+    let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
+
+    // Read the request: headers until blank line, then Content-Length bytes.
+    let mut buf = Vec::new();
+    let mut tmp = [0u8; 1];
+    while let Ok(n) = stream.read(&mut tmp) {
+        if n == 0 {
+            break;
+        }
+        buf.extend_from_slice(&tmp[..n]);
+        if buf.ends_with(b"\r\n\r\n") {
+            break;
+        }
+    }
+    let head = String::from_utf8_lossy(&buf).to_string();
+    let body_len = head
+        .split("\r\n")
+        .find_map(|l| {
+            l.to_ascii_lowercase()
+                .strip_prefix("content-length: ")
+                .and_then(|v| v.trim().parse::<usize>().ok())
+        })
+        .unwrap_or(0);
+    let mut body = buf;
+    while body.len() < head.len() + body_len {
+        let mut chunk = vec![0u8; head.len() + body_len - body.len()];
+        match stream.read(&mut chunk) {
+            Ok(0) => break,
+            Ok(n) => body.extend_from_slice(&chunk[..n]),
+            Err(_) => break,
+        }
+    }
+    let payload = &body[head.len()..];
+    let payload_str = String::from_utf8_lossy(payload).to_string();
+    if head.starts_with("POST") && head.contains("/chat/completions") {
+        bodies.lock().expect("bodies").push(payload_str);
+    }
+
+    let idx = bodies.lock().expect("bodies").len().saturating_sub(1);
+    let reply = replies
+        .get(idx)
+        .or_else(|| replies.last())
+        .cloned()
+        .unwrap_or_else(minimal_reply);
+
+    let resp = format!(
+        "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
+        reply.len(),
+        reply
+    );
+    let _ = stream.write_all(resp.as_bytes());
+    let _ = stream.flush();
+}
+
+fn minimal_reply() -> String {
+    sse_text("hello from the mock backend", true)
+}
+
+/// One SSE `data:` line carrying a chat-completion chunk with a text delta.
+fn sse_text(delta: &str, finish: bool) -> String {
+    let reason = if finish {
+        serde_json::Value::String("stop".into())
+    } else {
+        serde_json::Value::Null
+    };
+    let chunk = json!({
+        "choices": [{
+            "delta": { "content": delta },
+            "finish_reason": reason
+        }]
+    });
+    format!("data: {}\n\n", chunk)
+}
+
+/// A turn that emits `delta` and finishes — enough for a one-round run.
+fn one_text_turn(delta: &str) -> String {
+    sse_text(delta, true)
+}
+
+/// `max_turns` test: every reply carries a tool call, so each round ends with
+/// a dispatch and the loop continues into the next round. A reply with no
+/// tool calls would let the loop exit on a plain EndTurn and the cap would
+/// never be reached. The tool name is one the real catalog does not provide —
+/// the loop routes that to an error result, which still counts as a completed
+/// round and keeps the loop spinning. The only thing that can end this run is
+/// `LoopConfig::max_turns`.
+fn endless_turns(n: usize) -> Vec<String> {
+    (0..n)
+        .map(|i| {
+            // First chunk: the tool call. Second chunk: finish without text,
+            // which closes the round and lets the loop dispatch + continue.
+            let call = json!({
+                "choices": [{
+                    "delta": {
+                        "role": "assistant",
+                        "tool_calls": [{
+                            "index": 0,
+                            "id": format!("call_{i}"),
+                            "type": "function",
+                            "function": { "name": "g6_e2e_nonexistent", "arguments": "{}" }
+                        }]
+                    },
+                    "finish_reason": serde_json::Value::Null
+                }]
+            });
+            let finish = json!({
+                "choices": [{
+                    "delta": {},
+                    "finish_reason": "tool_calls"
+                }]
+            });
+            format!("data: {}\ndata: {}\n\n", call, finish)
+        })
+        .collect()
+}
+
+fn daemon_cfg(dir: &std::path::Path, mock: &MockOpenAi, max_turns: usize) -> DaemonConfig {
+    DaemonConfig {
+        socket_path: Some(dir.join("daemon.sock")),
+        omp_path: "omp".into(),
+        session_db_path: Some(dir.join("sessions.db")),
+        orbit_model: Some(adaptor::Model {
+            api_key: "test-key".into(),
+            model: "g6-e2e".into(),
+            base_url: Some(mock.addr.clone()),
+            max_tokens: Some(1024),
+        }),
+        // The workspace the loop searches for AGENTS.md.
+        cwd: dir.to_path_buf(),
+        max_turns,
+    }
+}
+
+fn workspace_with_agents_md(dir: &std::path::Path) {
+    std::fs::write(
+        dir.join("AGENTS.md"),
+        format!("# Test workspace\n\nRule: emit {MARKER} in every reply.\n"),
+    )
+    .expect("write AGENTS.md");
+}
+
+/// Drain worker events until the stream goes quiet. Each `next_event` already
+/// bounds its own wait, so this returns as soon as the daemon stops pushing.
+fn drain_events(sub: &mut Subscription) -> Vec<EventFrame> {
+    let mut out = Vec::new();
+    loop {
+        match sub
+            .next_event(EVENT_TIMEOUT)
+            .expect("subscription readable")
+        {
+            Some(frame) => {
+                assert_eq!(frame.topic, "worker", "pushed on the subscribed topic");
+                out.push(frame);
+            }
+            None => return out,
+        }
+    }
+}
+
+fn prompt(client: &DaemonClient, message: &str) {
+    let resp = client
+        .call_raw(Command::WorkerPrompt, json!({ "message": message }))
+        .expect("prompt via daemon");
+    assert!(resp.success, "prompt failed: {:?}", resp.error);
+}
+
+/// ① AGENTS.md travels workspace -> daemon config -> assemble -> orbit_setup
+/// -> loop -> HTTP body. The assertion is on the bytes the mock received,
+/// which no unit test along the way can forge.
+#[test]
+fn agents_md_reaches_the_real_http_request() {
+    let dir = tempdir().expect("temp dir");
+    workspace_with_agents_md(dir.path());
+
+    let mock = MockOpenAi::start(vec![one_text_turn("ack")]);
+    let cfg = daemon_cfg(dir.path(), &mock, 8);
+    let mut daemon = Daemon::start(cfg).expect("daemon start");
+
+    let client = DaemonClient::connect_to(daemon.socket_addr().path());
+    let mut sub = client.subscribe("worker").expect("subscribe");
+    prompt(&client, "ping");
+    drain_events(&mut sub);
+
+    let bodies = mock.received();
+    assert!(!bodies.is_empty(), "the loop made at least one HTTP call");
+
+    let joined = bodies.join("\n---\n");
+    assert!(
+        joined.contains(MARKER),
+        "AGENTS.md marker missing from the real request body"
+    );
+
+    drop(client);
+    daemon.shutdown();
+}
+
+/// ② `max_turns` in the config document caps the real run. The mock never
+/// finishes a turn, so a working cap is the only way this test terminates
+/// without timing out.
+#[test]
+fn max_turns_from_config_caps_the_real_run() {
+    let dir = tempdir().expect("temp dir");
+    std::fs::write(dir.path().join("AGENTS.md"), "# bare\n").expect("AGENTS.md");
+
+    let cap = 3;
+    // More rounds than the cap; each is an unfinished assistant turn.
+    let mock = MockOpenAi::start(endless_turns(12));
+    let cfg = daemon_cfg(dir.path(), &mock, cap);
+    let mut daemon = Daemon::start(cfg).expect("daemon start");
+
+    let client = DaemonClient::connect_to(daemon.socket_addr().path());
+    let mut sub = client.subscribe("worker").expect("subscribe");
+    prompt(&client, "go");
+
+    let events = drain_events(&mut sub);
+    let starts = events
+        .iter()
+        .filter(|f| f.event.get("event").and_then(Value::as_str) == Some("agent_start"))
+        .count();
+
+    // The loop runs exactly `cap` rounds and then stops on the cap.
+    assert_eq!(
+        starts, cap,
+        "the run must stop at max_turns={cap}, saw {starts} agent_start events"
+    );
+
+    drop(client);
+    daemon.shutdown();
+}
+
+/// ③ A daemon killed mid-run leaves an orphan; the next start closes it.
+/// This exercises the full `Daemon::start` repair path over a real DB file.
+#[test]
+fn restart_closes_orphaned_run() {
+    let dir = tempdir().expect("temp dir");
+    let db_path = dir.path().join("sessions.db");
+
+    // Process one: a run starts and the process dies before its TurnEnd.
+    {
+        let db = session::SessionDb::open(&db_path).expect("open db");
+        db.ensure_session("s1", "unfinished").expect("session row");
+        db.append_turn_log(
+            "s1",
+            &[session::TurnRecord::TurnStart {
+                run_id: "r1".into(),
+                ts_ms: 1_000,
+            }],
+        )
+        .expect("record start");
+    }
+
+    // Process two: same DB, fresh start. Repair runs before bind.
+    let mock = MockOpenAi::start(vec![one_text_turn("ack")]);
+    let cfg = daemon_cfg(dir.path(), &mock, 8);
+    let mut daemon = Daemon::start(cfg).expect("daemon start");
+
+    let records = daemon
+        .sessions()
+        .load_turn_log("s1")
+        .expect("read repaired log");
+    assert_eq!(records.len(), 2, "the orphan gained exactly one closer");
+    match &records[1] {
+        session::TurnRecord::TurnEnd { run_id, status, .. } => {
+            assert_eq!(run_id, "r1");
+            assert_eq!(*status, session::ABORTED, "the orphan is closed as aborted");
+        }
+        other => panic!("expected TurnEnd closer, got {other:?}"),
+    }
+
+    daemon.shutdown();
+}

diff --git a/crates/agent/orbit/tests/compaction_e2e.rs b/crates/agent/orbit/tests/compaction_e2e.rs
new file mode 100644
index 0000000..5005771
--- /dev/null
+++ b/crates/agent/orbit/tests/compaction_e2e.rs
@@ -0,0 +1,393 @@
+//! WP-B end-to-end compaction tests: a >120k-char long session drives the
+//! real char-budget policy all the way through the orbit loop (maintain
+//! hook → `orbit::compact_context` → harness `compact_with`) with no live
+//! LLM and no network.
+//!
+//! G3 acceptance ② — "`oi` starts one >120k-char long session and the
+//! compaction path survives end to end (checkpoint snapshot + keep-original
+//! on failure)". Every size below is measured with the policy's own
+//! `message_chars`, so the trigger is the genuine context size rather than
+//! a hardcoded constant assertion: each test asserts the fixture is really
+//! over (or just under) `COMPACT_CHAR_BUDGET` before it asserts anything
+//! about the outcome.
+//!
+//! Setup mirrors `tests/loop.rs`: a `Scripted` backend behind a `RefCell`
+//! replays canned turns (the summary stream is just another backend call,
+//! since `LlmSummarizer` routes the transcript through the same seam), and
+//! `filler`/`bulk` build 1000-char messages so the recent-window cut lands
+//! exactly on a message boundary.
+
+use std::cell::RefCell;
+use std::collections::HashSet;
+use std::sync::atomic::AtomicBool;
+
+use adaptor::{
+    Block, Content, Context, Message, Model, StopReason, StreamEvent, ToolCallSpec, ToolDef,
+};
+use omenic_harness_compaction::{
+    COMPACT_CHAR_BUDGET, KEEP_RECENT_CHARS, KEEP_RECENT_MIN, NoopSummarizer, RegionBudget,
+    SUMMARY_PREFIX, compact_with, is_balanced_at, recent_window_cut, to_dto,
+};
+use orbit::{ContextLog, LlmBackend, message_chars, run_agent, select_compaction_cut};
+use serde_json::json;
+use tempfile::tempdir;
+
+fn model() -> Model {
+    Model {
+        api_key: "k".into(),
+        model: "test".into(),
+        base_url: None,
+        max_tokens: None,
+    }
+}
+
+fn sig() -> AtomicBool {
+    AtomicBool::new(false)
+}
+
+/// One tool-call spec, for building assistant messages with `tool_use`
+/// blocks in the history (no tool is ever executed here).
+fn tc(id: &str) -> ToolCallSpec {
+    ToolCallSpec {
+        id: id.into(),
+        name: "echo_tool".into(),
+        args: json!({}),
+    }
+}
+
+/// A user message of exactly 1000 chars, tagged by index so the retained
+/// window and the summarized prefix stay identifiable in the transcript.
+fn filler(tag: usize) -> Message {
+    Message::user_text(format!("{tag:04}{}", "x".repeat(996)))
+}
+
+fn bulk(n: usize) -> Vec<Message> {
+    (0..n).map(filler).collect()
+}
+
+/// Scripted backend replays canned event lists per call (loop.rs pattern).
+struct Scripted {
+    turns: Vec<Vec<StreamEvent>>,
+    calls_made: usize,
+    seen_contexts: Vec<Context>,
+}
+
+impl Scripted {
+    fn new(turns: Vec<Vec<StreamEvent>>) -> Self {
+        Scripted {
+            turns,
+            calls_made: 0,
+            seen_contexts: vec![],
+        }
+    }
+}
+
+/// Trait takes `&self`; tests mutate through the RefCell (loop.rs pattern).
+struct Shared(RefCell<Scripted>);
+impl LlmBackend for Shared {
+    fn stream_cb(
+        &self,
+        _model: &Model,
+        context: &Context,
+        _tools: &[ToolDef],
+        _signal: &AtomicBool,
+        emit: &mut dyn FnMut(&StreamEvent),
+    ) {
+        let s = &mut *self.0.borrow_mut();
+        s.seen_contexts.push(context.clone());
+        let t = match s.turns.get(s.calls_made) {
+            Some(t) => t.clone(),
+            // Turns exhausted: end cleanly so the loop terminates.
+            None => vec![StreamEvent::Done {
+                stop_reason: StopReason::EndTurn,
+            }],
+        };
+        s.calls_made += 1;
+        for ev in &t {
+            emit(ev);
+        }
+    }
+}
+
+/// Total request size in the policy's own accounting: the system prompt
+/// (it rides every call and compaction cannot shrink it) plus messages.
+/// This is exactly what `compact_with` measures against the budget.
+fn request_chars(ctx: &Context) -> usize {
+    let system = ctx.system_prompt.as_deref().map_or(0, str::len);
+    system + ctx.messages.iter().map(message_chars).sum::<usize>()
+}
+
+/// Re-type wire messages into the harness DTO the policy operates on.
+fn dto(msgs: &[Message]) -> Vec<omenic_harness_compaction::Message> {
+    msgs.iter().map(to_dto).collect()
+}
+
+/// (tool_use ids, tool_result ids) carried by one message.
+fn tool_ids(m: &Message) -> (Vec<String>, Vec<String>) {
+    let Content::Blocks(bs) = &m.content else {
+        return (vec![], vec![]);
+    };
+    let mut uses = Vec::new();
+    let mut results = Vec::new();
+    for b in bs {
+        match b {
+            Block::ToolUse { id, .. } => uses.push(id.clone()),
+            Block::ToolResult { tool_use_id, .. } => results.push(tool_use_id.clone()),
+            _ => {}
+        }
+    }
+    (uses, results)
+}
+
+/// Every tool_call id / tool_result id left in a message list.
+fn pairing_ids(msgs: &[Message]) -> (HashSet<String>, HashSet<String>) {
+    let mut uses = HashSet::new();
+    let mut results = HashSet::new();
+    for m in msgs {
+        let (u, r) = tool_ids(m);
+        uses.extend(u);
+        results.extend(r);
+    }
+    (uses, results)
+}
+
+/// Orbit invariant 1 / dsh `toolPairingBalancedBefore`: every tool_call in
+/// the shipped context carries its matching tool_result and vice versa.
+fn pairing_balanced(msgs: &[Message]) -> bool {
+    let (uses, results) = pairing_ids(msgs);
+    uses == results
+}
+
+fn is_summary(m: &Message) -> bool {
+    match &m.content {
+        Content::Text(s) => s.starts_with(SUMMARY_PREFIX),
+        _ => false,
+    }
+}
+
+/// The transcript the summarizer saw, as plain text.
+fn transcript_of(ctx: &Context) -> &str {
+    match &ctx.messages[0].content {
+        Content::Text(s) => s.as_str(),
+        other => panic!("summary request should be plain text: {other:?}"),
+    }
+}
+
+/// A turn that streams `text` and ends the turn.
+fn answer_turn(text: &str) -> Vec<StreamEvent> {
+    vec![
+        StreamEvent::TextDelta(text.into()),
+        StreamEvent::Done {
+            stop_reason: StopReason::EndTurn,
+        },
+    ]
+}
+
+/// A summary stream that produces `gist`, followed by a turn answering `ok`.
+fn summary_then_ok(gist: &str) -> Vec<Vec<StreamEvent>> {
+    vec![answer_turn(gist), answer_turn("ok")]
+}
+
+#[test]
+fn long_session_over_budget_triggers_compaction() {
+    // 150 messages of exactly 1000 chars = 150,000 chars, well past the
+    // 120,000-char trigger. The maintenance hook runs before the first
+    // turn, so the summary stream is backend call #1 and the turn is #2.
+    let backend = Shared(RefCell::new(Scripted::new(summary_then_ok("the gist"))));
+    let mut ctx = Context {
+        system_prompt: Some("sys".into()),
+        messages: bulk(150),
+    };
+    assert!(
+        request_chars(&ctx) > COMPACT_CHAR_BUDGET,
+        "fixture must be a genuinely oversized session"
+    );
+
+    let _ = run_agent(&backend, &model(), &mut ctx, &[], &sig(), None);
+
+    let seen = backend.0.borrow();
+    // Two backend calls: the summary stream, then the turn itself — no
+    // third call, because the compacted context is back under budget.
+    assert_eq!(seen.calls_made, 2);
+    // The summary request covered the compactable prefix only.
+    let transcript = transcript_of(&seen.seen_contexts[0]);
+    assert!(
+        transcript.contains("0000"),
+        "oldest message must be summarized"
+    );
+    assert!(
+        !transcript.contains("0120"),
+        "kept window must not be summarized"
+    );
+    // The turn saw the summary marker plus the verbatim recent window.
+    assert_eq!(
+        seen.seen_contexts[1].messages.len(),
+        1 + KEEP_RECENT_CHARS / 1000
+    );
+    // The shipped context starts with the marker and is back inside the
+    // budget — compaction really cut it, not just rearranged messages.
+    assert_eq!(
+        ctx.messages[0],
+        Message::user_text(format!("{SUMMARY_PREFIX}the gist"))
+    );
+    assert!(request_chars(&ctx) < COMPACT_CHAR_BUDGET);
+}
+
+#[test]
+fn compaction_never_splits_tool_call_pairs() {
+    // A tool_use message far larger than the recent window pins the raw
+    // char-budget cut between the call and its result — exactly the spot
+    // that would orphan the result if the pairing guard didn't advance.
+    let mut msgs = bulk(100); // idx 0..99: 100,000 chars of history mass
+    msgs.push(Message::assistant("A".repeat(35_000), &[tc("t_edge")])); // 100
+    msgs.push(Message::tool_results(&[(
+        "t_edge".into(),
+        "edge result".into(),
+    )])); // 101
+    msgs.extend(bulk(2)); // 102, 103
+    // A complete pair inside the kept window that must survive verbatim.
+    msgs.push(Message::assistant("thinking".into(), &[tc("t_keep")])); // 104
+    msgs.push(Message::tool_results(&[(
+        "t_keep".into(),
+        "keep result".into(),
+    )])); // 105
+    msgs.push(filler(106)); // 106
+
+    let dto_msgs = dto(&msgs);
+    let raw_cut = recent_window_cut(&dto_msgs, KEEP_RECENT_CHARS, KEEP_RECENT_MIN);
+    assert!(
+        !is_balanced_at(&dto_msgs, raw_cut),
+        "raw window cut lands between a call and its result"
+    );
+    let cut = select_compaction_cut(&msgs, KEEP_RECENT_CHARS);
+    assert!(
+        cut > raw_cut,
+        "pairing guard must advance the cut past the orphan"
+    );
+    assert!(is_balanced_at(&dto_msgs, cut));
+
+    let backend = Shared(RefCell::new(Scripted::new(summary_then_ok("the gist"))));
+    let mut ctx = Context {
+        system_prompt: Some("sys".into()),
+        messages: msgs.clone(),
+    };
+    assert!(request_chars(&ctx) > COMPACT_CHAR_BUDGET);
+    let _ = run_agent(&backend, &model(), &mut ctx, &[], &sig(), None);
+
+    let seen = backend.0.borrow();
+    assert_eq!(seen.calls_made, 2);
+    // The straddling pair went into the summary TOGETHER: the transcript
+    // carries both the call and its result.
+    let transcript = transcript_of(&seen.seen_contexts[0]);
+    assert!(
+        transcript.contains("t_edge"),
+        "the orphan call must be summarized"
+    );
+    assert!(
+        transcript.contains("edge result"),
+        "its result must be summarized with it, not left orphaned"
+    );
+    assert!(
+        !transcript.contains("t_keep"),
+        "the surviving pair must stay verbatim"
+    );
+
+    // Shipped context: balanced, with exactly the surviving pair intact.
+    assert!(pairing_balanced(&ctx.messages));
+    let (uses, results) = pairing_ids(&ctx.messages);
+    assert_eq!(uses, results);
+    assert_eq!(uses, HashSet::from(["t_keep".to_string()]));
+    let kept_use = ctx
+        .messages
+        .iter()
+        .position(|m| tool_ids(m).0 == vec!["t_keep".to_string()])
+        .expect("surviving call must stay in the context");
+    assert_eq!(
+        tool_ids(&ctx.messages[kept_use + 1]).1,
+        vec!["t_keep".to_string()],
+        "its result must follow immediately"
+    );
+    assert!(request_chars(&ctx) < COMPACT_CHAR_BUDGET);
+}
+
+#[test]
+fn failed_summary_keeps_original_and_writes_no_checkpoint() {
+    // Policy level first: a summarizer that yields nothing is a pure no-op.
+    let dto_msgs = dto(&bulk(150));
+    let (out, summary) = compact_with(
+        &NoopSummarizer,
+        Some("sys"),
+        &dto_msgs,
+        COMPACT_CHAR_BUDGET,
+        &RegionBudget::default(),
+    );
+    assert!(summary.is_none());
+    assert_eq!(out, dto_msgs);
+
+    // End to end: the summary stream errors, so orbit invariant 4 must
+    // leave the context and the checkpoint log untouched (no panic).
+    let backend = Shared(RefCell::new(Scripted::new(vec![
+        vec![StreamEvent::Error("summary backend down".into())],
+        answer_turn("ok"),
+    ])));
+    let initial = bulk(150);
+    let mut ctx = Context {
+        system_prompt: Some("sys".into()),
+        messages: initial.clone(),
+    };
+    assert!(request_chars(&ctx) > COMPACT_CHAR_BUDGET);
+    let dir = tempdir().unwrap();
+    let log_path = dir.path().join("ctx.jsonl");
+    let log = ContextLog::new(&log_path);
+    for m in &initial {
+        log.append_message(m).unwrap();
+    }
+
+    let _ = run_agent(&backend, &model(), &mut ctx, &[], &sig(), Some(&log));
+
+    // In-memory context: only the final reply appended, no marker injected.
+    assert_eq!(ctx.messages.len(), initial.len() + 1);
+    assert!(ctx.messages.iter().take(initial.len()).eq(initial.iter()));
+    assert!(ctx.messages.iter().all(|m| !is_summary(m)));
+    // The turn ran against every original message — nothing was dropped.
+    let seen = backend.0.borrow();
+    assert_eq!(seen.calls_made, 2);
+    assert_eq!(seen.seen_contexts[1].messages, initial);
+    // Checkpoint snapshot: the replayed log is the pre-compaction
+    // conversation followed by the reply — no compaction marker anywhere.
+    let replayed = ContextLog::load(&log_path).unwrap();
+    assert_eq!(replayed.len(), initial.len() + 1);
+    assert!(replayed.starts_with(initial.as_slice()));
+    assert_eq!(replayed[initial.len()], ctx.messages[initial.len()]);
+}
+
+#[test]
+fn session_just_under_budget_triggers_no_compaction() {
+    // Exactly one character under the trigger: the boundary itself is
+    // probed, not a comfortably small context. The system prompt counts
+    // toward the budget, so it carries the remaining slack.
+    let messages = bulk(119); // 119,000 chars
+    let under = COMPACT_CHAR_BUDGET.saturating_sub(1);
+    assert!(
+        under > 119_000,
+        "fixture assumes the char budget exceeds 119k characters"
+    );
+    let mut ctx = Context {
+        system_prompt: Some("s".repeat(under - 119_000)),
+        messages,
+    };
+    assert_eq!(request_chars(&ctx), COMPACT_CHAR_BUDGET - 1);
+    let before = ctx.messages.clone();
+
+    let backend = Shared(RefCell::new(Scripted::new(vec![answer_turn("ok")])));
+    let _ = run_agent(&backend, &model(), &mut ctx, &[], &sig(), None);
+
+    // Exactly one backend call — the turn itself. No summary stream.
+    let seen = backend.0.borrow();
+    assert_eq!(seen.calls_made, 1);
+    assert_eq!(seen.seen_contexts[0].messages, before);
+    // Originals untouched; only the final reply was appended.
+    assert_eq!(ctx.messages.len(), before.len() + 1);
+    assert!(ctx.messages.iter().take(before.len()).eq(before.iter()));
+    assert!(ctx.messages.iter().all(|m| !is_summary(m)));
+}

