+//! 指示器区块：StatusDot（状态点）与 Badge（徽标）。
+//!
+//! Indicators = 贴在别的内容上、表达状态或标记的**非交互**小零件。这里演示的是 kit 的
+//! 公共件（`ui_kit::StatusDot` / `ui_kit::Badge`），样式真身在 kit 资产
+//! `indicators.css` / `badge.css`；本文件不写任何尺寸或色值。
+//!
+//! Badge 面板函数复用自 [`primitives`](super::primitives)（导航再分组，锚点 id 不变），
+//! 与 `containers.rs` 借 `widgets::p_poster` 同一手法。
+
+use dioxus::prelude::*;
+use ui_kit::StatusDot;
+
+/// 指示器区块。
+pub fn section_indicators() -> Element {
+    rsx! {
+        section { id: "indicators", class: "demo-section",
+            div { class: "demo-section-head",
+                h2 { class: "role-title", "指示器 · StatusDot / Badge" }
+                p { class: "role-desc",
+                    "贴在内容上的非交互小零件：状态点亮态实心语义色、灭态实心灰点（两态同尺寸同形状，只差色相）；徽标承载文字。"
+                }
+                crate::coverage::SectionBadges { section: "indicators" }
+            }
+            { p_status_dot() }
+            { super::primitives::p_badge() }
+        }
+    }
+}
+
+/// 一个语义档的样例行：亮 / 灭两颗 + 档位名。
+fn tone_row(tone: &'static str, test_id: &'static str) -> Element {
+    rsx! {
+        div { class: "cov-dot-item",
+            StatusDot { on: true, tone: Some(tone), "data-testid": "{test_id}-on" }
+            StatusDot { on: false, tone: Some(tone), "data-testid": "{test_id}-off" }
+            span { class: "cov-dot-name", "{tone}" }
+        }
+    }
+}
+
+/// StatusDot —— neutral 缺省档 + 四个语义档，每档亮灭并排。
+///
+/// 与表单开关右端那颗点同源（形状与两态定义在 kit `indicators.css`）；kit-demo 用量矩阵
+/// 的项目点也用它，`data-tone` 传项目名、品牌色由 demo 侧 CSS 补档。
+fn p_status_dot() -> Element {
+    rsx! {
+        div { id: "indicators-dot", class: "ui-section demo-panel",
+            p { class: "role-label", "StatusDot — 缺省 neutral + success / warning / danger / info" }
+            div { class: "demo-row--spaced",
+                { tone_row("neutral", "dot-neutral") }
+                { tone_row("success", "dot-success") }
+                { tone_row("warning", "dot-warning") }
+                { tone_row("danger", "dot-danger") }
+                { tone_row("info", "dot-info") }
+            }
+            p { class: "role-desc",
+                "灭态是实心灰点：两态同尺寸同形状，切换不跳位。neutral 档亮灭同为 --muted-foreground，所以那一对取值相同。"
+            }
+        }
+    }
+}
