--- /dev/null
+++ b/apps/kit-demo/tests/panel_testid.mjs
@@ -0,0 +1,188 @@
+// kit-demo 面板的 DOM 侧回归：稳定测试钩子 + 圆点两态的实际样式值。
+//
+// 为什么不是 cargo 测试：本仓 ui-kit 的测试跑在 dioxus VirtualDom 的 `VirtualDom`
+// 宿主侧（tests/*.rs，如 switch_row_contract.rs），那里读不到「最终 DOM 上的属性集合」——
+// dioxus 0.7.10 在本 workspace 里没有可用的 SSR 渲染器（`dioxus-fullstack` 0.7.10 无
+// `ssr::render_to_string`，Cargo.lock 里也没有 dioxus-ssr），rsx 上的动态属性在宿主测试
+// 里只能看到模板槽位，看不到运行期属性。而 data-testid 会不会真的落到 DOM 上，取决于
+// dioxus 的属性差分（KeyId::hash 目前对 AttributeValue::Dynamic 不编码值，同标签多个
+// 动态属性会互相顶掉），只能在真浏览器里断言。这条脚本补的正是这一段。
+//
+// 跑法（与 justfile 的 dev-web 车道同源，不新起基建）：
+//   1. `just dev-web debug`（或本 app 的 `dx serve`）起页面，记下端口
+//   2. 起一个带远程调试口的 headless 浏览器。本机没有 `chromium` 这个可执行名，用
+//      playwright 自带那份（路径里的版本号随 playwright 升级变）：
+//        ~/.cache/ms-playwright/chromium-1243/chrome-linux/chrome \
+//          --headless=new --remote-debugging-port=9333 --user-data-dir=/tmp/omp-cdp about:blank
+//   3. KIT_DEMO_URL=http://127.0.0.1:11585 KIT_CDP_URL=http://127.0.0.1:9333 \
+//        bun apps/kit-demo/tests/panel_testid.mjs
+// 没给 KIT_DEMO_URL 或连不上 CDP -> 记 SKIP 并退出 0（无浏览器环境不假红）。
+// 页面可达但断言不过 -> 退出 1。
+const DEMO = process.env.KIT_DEMO_URL;
+const CDP = process.env.KIT_CDP_URL || "http://127.0.0.1:9333";
+if (!DEMO) {
+  console.log("SKIP 未给 KIT_DEMO_URL（页面未启动）：DOM 侧断言需要真实浏览器，见文件头跑法");
+  process.exit(0);
+}
+let ver;
+try {
+  ver = await (await fetch(`${CDP}/json/version`, { signal: AbortSignal.timeout(3000) })).json();
+} catch {
+  console.log(`SKIP 连不上 CDP ${CDP}（chromium 未起远程调试口）：见文件头跑法`);
+  process.exit(0);
+}
+
+let id = 0;
+const pend = new Map();
+const ws = new WebSocket(ver.webSocketDebuggerUrl);
+ws.onmessage = (ev) => {
+  const m = JSON.parse(ev.data);
+  if (m.id && pend.has(m.id)) {
+    pend.get(m.id)(m);
+    pend.delete(m.id);
+  }
+};
+await new Promise((r) => (ws.onopen = r));
+const send = (method, params = {}, sessionId) =>
+  new Promise((res) => {
+    const mid = ++id;
+    pend.set(mid, res);
+    ws.send(JSON.stringify({ id: mid, method, params, ...(sessionId ? { sessionId } : {}) }));
+  });
+const t = await send("Target.createTarget", { url: `${DEMO}/#forms-panel` });
+const a = await send("Target.attachToTarget", { targetId: t.result.targetId, flatten: true });
+const sid = a.result?.sessionId ?? a.sessionId;
+await send("Runtime.enable", {}, sid);
+await send("Page.enable", {}, sid);
+// wasm 崩溃时 dioxus 默认注入整屏错误对话框，会盖住被断言的元素；本脚本自己看控制台。
+await send("Page.setBypassCSP", { enabled: true }, sid);
+await send("Page.addScriptToEvaluateOnNewDocument", { source: "window.__errors = [];" }, sid);
+await send("Runtime.evaluate", { expression: "location.reload()" }, sid);
+await send("Emulation.setDeviceMetricsOverride", { width: 1496, height: 922, deviceScaleFactor: 1, mobile: false }, sid);
+const ev = (expression) => send("Runtime.evaluate", { expression, returnByValue: true }, sid);
+const val = async (expression) => (await ev(expression)).result?.result?.value;
+
+// dx serve 首帧要等 wasm 装配；轮询到面板出现（上限 ~60s，比固定 sleep 稳）。
+let up = false;
+for (let i = 0; i < 40; i++) {
+  await new Promise((r) => setTimeout(r, 1500));
+  if (await val("!!document.querySelector('[data-testid=\"panel-form\"]')")) {
+    up = true;
+    break;
+  }
+}
+if (!up) {
+  console.log(`FAIL 页面 60s 内没渲染出面板（${DEMO}）——先看 wasm 是否构建成功`);
+  await send("Target.closeTarget", { targetId: t.result.targetId });
+  ws.close();
+  process.exit(1);
+}
+await new Promise((r) => setTimeout(r, 1200));
+
+let bad = 0;
+const ok = (name, cond, detail) => {
+  console.log(`${cond ? "PASS" : "FAIL"} ${name}${detail ? ` -> ${detail}` : ""}`);
+  if (!cond) bad++;
+};
+
+// 1) 三条批注涉及的行都有稳定钩子（AIN 侧栏按 data-testid 定位批注目标）
+const rows = await ev(`(() => {
+  const want = ["panel-form","panel-card","panel-preset","panel-foil","panel-idle","panel-shadow"];
+  return JSON.stringify(want.map(id => [id, !!document.querySelector('[data-testid="'+id+'"]')]));
+})()`);
+for (const [rid, found] of JSON.parse(rows.result.result.value)) ok(`钩子 ${rid}`, found);
+
+// 2) 整行是唯一的按钮：开关行内不得再有嵌套控件（曾经的右侧 switch 会抢焦点）
+const inner = await val(`document.querySelectorAll('[data-testid="panel-idle"] button, [data-testid="panel-idle"] input, [data-testid="panel-idle"] [role="switch"]').length`);
+ok("开关行内无嵌套控件", inner === 0, `inner=${inner}`);
+ok("开关行本体是 switch 语义", (await val(`document.querySelector('[data-testid="panel-idle"]').getAttribute('role')`)) === "switch");
+
+// 3) 圆点在最右端（圆点右缘到床右边距 == 配方 ml-auto 定死的 12px），两态几何一致
+const geom = async () =>
+  JSON.parse(
+    (
+      await ev(`(() => {
+        const row = document.querySelector('[data-testid="panel-idle"]');
+        const bed = document.querySelector('[data-testid="panel-card"]');
+        const dot = row.querySelector('.ui-switch-row-dot');
+        if (!row || !bed || !dot) return '{"err":"missing"}';
+        const dr = dot.getBoundingClientRect(), br = bed.getBoundingClientRect();
+        return JSON.stringify({ right: Math.round(br.right - dr.right), w: Math.round(dr.width),
+          state: row.getAttribute('data-state') });
+      })()`)
+    ).result.result.value
+  );
+const g1 = await geom();
+ok("圆点贴床最右（right=12px）", g1.right === 12, JSON.stringify(g1));
+
+// 4) 两态样式值：启用=实心绿、停用=灰色描边空心；键盘翻转（坐标点击在入场动画期会打偏）
+const dotStyle = (prop) =>
+  val(`(() => { const d = document.querySelector('[data-testid="panel-idle"] .ui-switch-row-dot');
+       const c = getComputedStyle(d); return c.${prop}; })()`);
+const onBg = await dotStyle("backgroundColor");
+const onBorder = await dotStyle("borderTopColor");
+ok("启用态实心（border 透明）", /rgba\(0, 0, 0, 0\)|transparent/.test(onBorder), `${onBg} / ${onBorder}`);
+await ev(`(() => { const f = [...document.querySelectorAll('button,input,select')].filter(e => e.getBoundingClientRect().width > 0);
+       const i = f.findIndex(e => e.getAttribute('data-testid') === 'panel-idle'); f[i-1].focus(); })()`);
+for (const type of ["keyDown", "keyUp"]) {
+  await send("Input.dispatchKeyEvent", { type, key: "Tab", code: "Tab", windowsVirtualKeyCode: 9 }, sid);
+}
+await new Promise((r) => setTimeout(r, 250));
+for (const type of ["keyDown", "keyUp"]) {
+  await send("Input.dispatchKeyEvent", { type, key: " ", code: "Space", text: " ", windowsVirtualKeyCode: 32 }, sid);
+}
+await new Promise((r) => setTimeout(r, 600));
+ok("键盘 Space 翻转状态位", (await val(`document.querySelector('[data-testid="panel-idle"]').getAttribute('data-state')`)) === "unchecked");
+const offBg = await dotStyle("backgroundColor");
+const offBorder = await dotStyle("borderTopColor");
+ok("停用态空心（bg 透明、border 有色）", /rgba\(0, 0, 0, 0\)|transparent/.test(offBg) && !/rgba\(0, 0, 0, 0\)|transparent/.test(offBorder), `${offBg} / ${offBorder}`);
+const g2 = await geom();
+ok("两态几何一致", g1.right === g2.right && g1.w === g2.w, `${JSON.stringify(g1)} vs ${JSON.stringify(g2)}`);
+ok("整行焦点是自定义环（无 UA 双描边）", (await val(`getComputedStyle(document.querySelector('[data-testid="panel-idle"]')).outlineStyle`)) === "none");
+
+// 5) 选择行按钮占满床宽
+const widths = JSON.parse(
+  (
+    await ev(`(() => { const bedEl = document.querySelector('[data-testid="panel-card"]');
+      const trigEl = bedEl && bedEl.querySelector('button');
+      if (!bedEl || !trigEl) return '{"err":true}';
+      const bed = bedEl.getBoundingClientRect(), trig = trigEl.getBoundingClientRect();
+      return JSON.stringify({ bed: Math.round(bed.width), trig: Math.round(trig.width) }); })()`)
+  ).result.result.value
+);
+ok("选择行按钮占满行宽", !widths.err && Math.abs(widths.bed - widths.trig) <= 1, JSON.stringify(widths));
+
+// 6) hex 输入框焦点无蓝框（输入框无环 + 行壳 box-shadow 压掉）。元素缺失时判 FAIL，不抛异常。
+await ev(`document.querySelector('input[aria-label="Foil Color hex"]')?.focus()`);
+const hex = JSON.parse(
+  (
+    await ev(`(() => { const el = document.querySelector('input[aria-label="Foil Color hex"]');
+      const row = el && el.closest('[data-testid="panel-foil"]');
+      if (!el || !row) return '{"row":false}';
+      return JSON.stringify({ row: true, inputShadow: getComputedStyle(el).boxShadow,
+        outlineStyle: getComputedStyle(el).outlineStyle, rowShadow: getComputedStyle(row).boxShadow }); })()`)
+  ).result.result.value
+);
+ok("hex 输入框存在", hex.row);
+// outline-width 在 outline-style:none 下仍报告初值 2px（Chrome 行为），真正决定画不画的是 style。
+ok("hex 输入框 focus 无蓝框", !!hex.row && hex.inputShadow === "none" && hex.outlineStyle === "none" && hex.rowShadow === "none", JSON.stringify(hex));
+
+// 7) 亮色主题同口径（demo 的主题按钮实测不改 data-theme，这里按主题机制本身设属性）
+await ev(`document.documentElement.setAttribute('data-theme','light')`);
+await new Promise((r) => setTimeout(r, 500));
+const lightOffBg = await dotStyle("backgroundColor");
+const lightOffBorder = await dotStyle("borderTopColor");
+// 此刻状态位是 unchecked（第 4 步键盘翻转过），空心口径与暗色同：bg 透明 + border 有色。
+ok("亮色停用态仍空心",
+  /rgba\(0, 0, 0, 0\)|transparent/.test(lightOffBg) && !/rgba\(0, 0, 0, 0\)|transparent/.test(lightOffBorder),
+  `${lightOffBg} / ${lightOffBorder}`);
+await ev(`document.documentElement.setAttribute('data-theme','dark')`);
+
+// 8) 控制台无 wasm 崩溃
+const errs = (await val("JSON.stringify(window.__errors || [])")) || "[]";
+ok("无运行时异常", JSON.parse(errs).length === 0, errs.slice(0, 200));
+
+await send("Target.closeTarget", { targetId: t.result.targetId });
+ws.close();
+console.log(bad === 0 ? "ALL PASS" : `FAILED ${bad}`);
+process.exit(bad === 0 ? 0 : 1);
