diff --git a/crates/web/ui-kit/tests/switch_row_contract.rs b/crates/web/ui-kit/tests/switch_row_contract.rs
new file mode 100644
index 0000000..f2a9544
--- /dev/null
+++ b/crates/web/ui-kit/tests/switch_row_contract.rs
@@ -0,0 +1,274 @@
+//! `SwitchRow` 契约：运行时状态位账本 + 样式侧的非颜色状态线索。
+//!
+//! 为什么钉这条（批注 bdef187c 的回归线）：这一行的形态刚从「`div[role=group]` + 右侧
+//! 内嵌 [`Switch`](ui_kit::Switch)」改成「整行 `button[role=switch]` + 右端状态圆点」。
+//! 两套语义混在一起时页面不报错，但消费端会同时看到两颗开关：多一个 Tab 停靠点、读屏把
+//! 同一个状态读两遍，行上的 `data-state`（圆点的形态与配色都靠它选样式）还会与内层
+//! switch 的同名属性打架。所以这里钉两层：运行侧钉**状态位的数量与同步性**，
+//! 样式侧钉**状态线索的表达方式**，每条都对应一种真实回归形态：
+//!
+//! 1. 一次状态翻转里 `data-state` / `aria-checked` 各只发一份——旧结构行是 `group`、
+//!    状态在内层那颗 switch 上；若有人把 `Switch` 再嵌回来，同一帧就会发两份；
+//! 2. `aria-checked`（读屏真相）与 `data-state`（CSS 选形态）成对翻转且不留旧值——任一漏改
+//!    就是「点完看着还绿、读屏说 false」的静默分岔。
+//! 3. 圆点状态必须带**非颜色**线索：开=实心盘、关=空心描边环，两态在「填充 / 描边」
+//!    这条通道上取值相反——只差色相在红绿色觉下等同不可分（WCAG 1.4.1）；
+//! 4. 行本体是 `button`，UA 焦点描边必须显式复位，否则键盘聚焦时与设计焦点环叠成双影。
+//!
+//! 技术注记（dioxus 0.7.10 实测）：**挂载帧不发动态属性**——静态与首帧属性都随模板装载，
+//! `Mutation::SetAttribute` 只在值变化时出现（未变化的属性被 diff 吞掉，首帧一条也不发）。
+//! 因此本文件全部断言走「改值后的 diff」，不假装能看穿模板。
+//!
+//! 覆盖边界：DOM 结构与几何（行本体 `BUTTON.ui-form-row.ui-switch-row[role=switch]`、子级
+//! `span.ui-form-row-label` + `span.ui-switch-row-dot[aria-hidden=true]`、圆点 8×8、距床右
+//! 边界 12px、点整行后 `aria-checked` true→false→true、键盘 Tab 后 `outline-style: none`）
+//! 由一次性无头 Chromium CDP 探针实测核对，脚本不入库（要跑就得配一套服务与浏览器，
+//! 属另一套基建）；**样式真身里的状态线索由本文件末尾的 css 契约断言守住**——两个
+//! blocker 的修复全在 css 里，只靠人工测量守不住后续改动。
+
+use std::cell::RefCell;
+use std::rc::Rc;
+
+use dioxus::core::{AttributeValue, Mutation, VirtualDom};
+use dioxus::prelude::*;
+use ui_kit::SwitchRow;
+
+thread_local! {
+    /// 受控 `checked` 的句柄盒子（信号必须在活跃 runtime 里创建，故经根组件递出）。
+    static CHECKED_BOX: Rc<RefCell<Option<Signal<bool>>>> = Default::default();
+}
+
+fn root() -> Element {
+    let box_ = use_root_context(|| CHECKED_BOX.with(Rc::clone));
+    let checked = use_signal(|| true);
+    let c0 = checked;
+    let b0 = box_;
+    use_effect(move || {
+        *b0.borrow_mut() = Some(c0);
+    });
+    rsx! {
+        SwitchRow {
+            label: "Glow",
+            checked: c0(),
+            on_checked_change: move |_: bool| {},
+            "data-testid": "probe-switch-row",
+        }
+    }
+}
+
+/// 一次渲染产出里的动态属性账本 `(名字, 字符串值)`；监听器等非字面值跳过。
+fn attr_edits(edits: &[Mutation]) -> Vec<(&'static str, String)> {
+    let mut out = Vec::new();
+    for m in edits {
+        if let Mutation::SetAttribute { name, value, .. } = m {
+            let text = match value {
+                AttributeValue::Text(s) => Some(s.clone()),
+                AttributeValue::Bool(b) => Some(b.to_string()),
+                _ => None,
+            };
+            if let Some(v) = text {
+                out.push((*name, v));
+            }
+        }
+    }
+    out
+}
+
+/// 挂载受控样本并把 `checked` 从 true 改成 false，返回那一帧的属性账本。
+///
+/// 走「真改值」而不是 `mark_all_dirty`：后者重渲染时属性未变，diff 一条 SetAttribute
+/// 都不发（见模块头的技术注记），拿它看不出状态位。
+fn flip_to_off() -> Vec<(&'static str, String)> {
+    let mut dom = VirtualDom::prebuilt(root);
+    dom.process_events(); // 挂载 effect 递出信号句柄
+    let mut checked = CHECKED_BOX
+        .with(|b| b.take())
+        .expect("挂载 effect 应递出受控信号句柄");
+    checked.set(false);
+    dom.process_events();
+    attr_edits(&dom.render_immediate_to_vec().edits)
+}
+
+/// 某个名字的属性值全部取出来（顺序 = diff 顺序）。
+fn values<'a>(attrs: &'a [(&'static str, String)], name: &str) -> Vec<&'a str> {
+    attrs
+        .iter()
+        .filter(move |(n, _)| *n == name)
+        .map(|(_, v)| v.as_str())
+        .collect()
+}
+
+#[test]
+fn one_toggle_emits_exactly_one_state_bit_each() {
+    let attrs = flip_to_off();
+
+    assert_eq!(
+        values(&attrs, "data-state"),
+        vec!["unchecked"],
+        "圆点选色只认行上这一份 data-state；把内层 Switch 嵌回来会同一帧发两份"
+    );
+    assert_eq!(
+        values(&attrs, "aria-checked"),
+        vec!["false"],
+        "整行只有一个开关状态要播报（旧结构里行是 group、状态在里层那颗 switch 上）"
+    );
+}
+
+#[test]
+fn aria_checked_and_data_state_flip_together_without_leftovers() {
+    let attrs = flip_to_off();
+
+    let state = values(&attrs, "data-state");
+    let aria = values(&attrs, "aria-checked");
+    assert_eq!(state, vec!["unchecked"], "圆点要变灰：{state:?}");
+    assert_eq!(aria, vec!["false"], "读屏要跟着翻：{aria:?}");
+
+    let stale: Vec<&str> = state
+        .into_iter()
+        .chain(aria)
+        .filter(|v| *v == "true" || *v == "checked")
+        .collect();
+    assert!(
+        stale.is_empty(),
+        "两个状态位不能一个翻一个不翻——圆点与读屏会分岔：{stale:?}"
+    );
+}
+
+// ---------------------------------------------------------------------------
+// 样式侧契约：状态必须带非颜色线索（WCAG 1.4.1），焦点线索只有一套
+//
+// 上面两条钉运行时账本，这一组钉样式真身。断言先按选择器取规则块、再看块内声明，
+// 不做全文 grep——全文匹配会被注释或别的规则误判成绿。
+// ---------------------------------------------------------------------------
+
+const FORM_CSS: &str = include_str!("../assets/custom-form.css");
+
+/// 剥块注释：注释里出现的属性名不算声明。
+fn strip_block_comments(css: &str) -> String {
+    let mut out = String::with_capacity(css.len());
+    let mut rest = css;
+    while let Some(i) = rest.find("/*") {
+        out.push_str(&rest[..i]);
+        rest = rest[i..]
+            .find("*/")
+            .map(|j| &rest[i + j + 2..])
+            .unwrap_or_default();
+    }
+    out.push_str(rest);
+    out
+}
+
+/// 某个选择器规则块的内容（花括号配对；同一选择器多处出现则全部返回）。
+/// 选择器必须整段出现且紧跟 `{`（允许空白），避免 `.ui-switch-row` 命中
+/// `.ui-switch-row-dot` 这类前缀。
+fn rule_bodies(selector: &str) -> Vec<String> {
+    let css = strip_block_comments(FORM_CSS);
+    let bytes = css.as_bytes();
+    let mut out = Vec::new();
+    let mut from = 0;
+    while let Some(hit) = css[from..].find(selector) {
+        let after = from + hit + selector.len();
+        let Some(rel) = css[after..].find(|c: char| !c.is_whitespace()) else {
+            break;
+        };
+        let head = after + rel;
+        if bytes.get(head) == Some(&b'{') {
+            let mut depth = 0usize;
+            for j in head..bytes.len() {
+                match bytes[j] {
+                    b'{' => depth += 1,
+                    b'}' => {
+                        depth -= 1;
+                        if depth == 0 {
+                            out.push(css[head + 1..j].to_string());
+                            break;
+                        }
+                    }
+                    _ => {}
+                }
+            }
+        }
+        from = after;
+    }
+    out
+}
+
+/// 把规则块压成单行，便于跨行写值时仍能匹配到声明。
+fn flatten(body: &str) -> String {
+    body.split_whitespace().collect::<Vec<_>>().join(" ")
+}
+
+/// 行本体是 `button`：必须显式复位 UA 焦点描边，否则键盘聚焦时 UA auto 描边与
+/// `.ui-form-row:focus-visible` 的 3px 环叠成双影（审查 blocker 1.5 的回归线）。
+#[test]
+fn row_button_resets_ua_focus_outline() {
+    let blocks: Vec<String> = rule_bodies(".ui-switch-row")
+        .iter()
+        .map(|b| flatten(b))
+        .collect();
+    assert!(!blocks.is_empty(), "找不到 .ui-switch-row 规则块");
+    assert!(
+        blocks
+            .iter()
+            .any(|b| b.contains("outline-none") || b.contains("outline-hidden")),
+        "行本体是 button，不复位 UA outline 就会出现两套焦点线索：{blocks:?}"
+    );
+}
+
+/// 状态不许只靠色相（WCAG 1.4.1）：开=实心、关=空心，两态在「填充 / 描边」这条非色
+/// 通道上必须取值相反。灰色已从 background 移到 border-color，所以「关态底色透明 +
+/// 描边可见」是硬约束——把它改回实心灰，本条必须红。
+#[test]
+fn dot_encodes_state_by_shape_not_hue_only() {
+    let base: String = rule_bodies(".ui-switch-row-dot")
+        .iter()
+        .map(|b| flatten(b))
+        .collect();
+    assert!(
+        base.contains("border-2") && base.contains("border-transparent"),
+        "圆点要常驻 2px 透明边框，两态外圈几何才一致（8×8、右距 12px 不跳位）：{base}"
+    );
+
+    let on: String = rule_bodies(r#".ui-switch-row[data-state="checked"] .ui-switch-row-dot"#)
+        .iter()
+        .map(|b| flatten(b))
+        .collect();
+    let off: String = rule_bodies(r#".ui-switch-row[data-state="unchecked"] .ui-switch-row-dot"#)
+        .iter()
+        .map(|b| flatten(b))
+        .collect();
+    assert!(
+        on.contains("var(--success-foreground)"),
+        "开态要是实心 success 盘：{on}"
+    );
+    assert!(
+        !on.contains("border-color: var("),
+        "开态描边必须保持透明，否则与关态只差色相：{on}"
+    );
+    assert!(
+        off.contains("background-color: transparent"),
+        "关态底色必须透明（只剩描边这条形状线索）：{off}"
+    );
+    assert!(
+        off.contains("border-color: var(--muted-foreground)"),
+        "关态描边必须可见：{off}"
+    );
+}
+
+/// 两个通道同节奏过渡：只过渡 background 的话，切换中途描边会瞬现/瞬隐。
+#[test]
+fn dot_transitions_both_state_channels() {
+    let base: String = rule_bodies(".ui-switch-row-dot")
+        .iter()
+        .map(|b| flatten(b))
+        .collect();
+    let value = base
+        .split("transition:")
+        .nth(1)
+        .and_then(|rest| rest.split(';').next())
+        .unwrap_or_default();
+    assert!(
+        value.contains("background-color") && value.contains("border-color"),
+        "background 与 border-color 必须一起过渡，中途才不会一半已变一半没变：{value:?}"
+    );
+}

