+    let mut frame = use_signal(|| 4.0f64);
+    let mut glare = use_signal(|| 0.5f64);
+    let mut tilt = use_signal(|| 14.0f64);
+    let mut hover_scale = use_signal(|| 1.04f64);
+    let mut radius = use_signal(|| 14.0f64);
+    let mut width = use_signal(|| 320.0f64);
+    let mut idle_shimmer = use_signal(|| true);
+    let mut shadow = use_signal(|| true);
