+        || preset() != card_default_preset(&card())
+        || foil() != "#e2e6ec"
+        || intensity() != 0.85
+        || scale() != 1.0
+        || edge_sparkle() != 0.8
+        || frame() != 4.0
+        || glare() != 0.5
+        || tilt() != 14.0
