+// 登录/注册页 page object（#login / #signup 路由，hash 直达）。
+//
+// 与 AdminPage 的区别：登录页在 auth hash 下渲染独立 AuthPageRoot，
+// 不走 admin 标签框架。本 POM 只做登录表单的交互与断言。
+//
+// 选择器口径（ui-validation 约定）：占位文案 + role/name，不用 class 选择器。
+// 输入框无 data-testid（表单在 crates/web/auth 的 ui-kit Input 组件），
+// 用稳定的 placeholder 文案定位；提交按钮用 role+name。
+//
+// 凭据：dev 种子账号 admin_dev（db/dev/generate_seed.py），仅本地 dev 后端有效；
+// 本套件只跑在 dev 档，不指向生产。
+
+import { expect, type Page } from '@playwright/test';
+
+export class LoginPage {
+  constructor(
+    private page: Page,
+    private baseUrl: string,
+  ) {}
+
+  /**
+   * 直达 #login（绕开启动恢复路径；空白 context 下无 token 污染）。
+   * dx serve 首建时伺服的是 "We're building your app now" splash 页：
+   * 不等 `load`/`domcontentloaded`（splash 长轮询，文档事件未必触发），
+   * `commit` 即返回，之后等登录按钮出现 = 应用真正就绪（splash 退出）。
+   */
+  async open(): Promise<void> {
+    await this.page.goto(`${this.baseUrl}/#login`, { waitUntil: 'commit' });
+    await this.page.getByRole('button', { name: 'Sign in' }).waitFor({ timeout: 120_000 });
+  }
+
+  /** 填入登录表单。 */
+  async fill(username: string, password: string): Promise<void> {
+    await this.page.getByPlaceholder('name@example.com').fill(username);
+    await this.page.getByPlaceholder('••••••••').fill(password);
+  }
+
+  /**
+   * 提交登录，返回 /api/user/login 的响应状态码。
+   * 等真实网络响应（POM 层不写死业务判定，断言留给 spec 层）。
+   */
+  async submit(): Promise<number> {
+    const respPromise = this.page
+      .waitForResponse(
+        (r) => r.url().includes('/api/user/login') && r.request().method() === 'POST',
+      )
+      .then((r) => r.status());
+    await this.page.getByRole('button', { name: 'Sign in' }).click();
+    return respPromise;
+  }
+  /**
+   * 访问令牌（登录态持久键）。Remember 未勾选时落 sessionStorage，
+   * 勾选/自动登录落 localStorage：两处都查，返回首个命中。
+   */
