diff --git a/e2e/specs/login.spec.ts b/e2e/specs/login.spec.ts
new file mode 100644
index 0000000..2a69168
--- /dev/null
+++ b/e2e/specs/login.spec.ts
@@ -0,0 +1,41 @@
+// 登录页（#login）e2e：真实手填登录 + 错误凭据路径。
+//
+// 为什么需要这个 spec：其余用例全部跑在 debug-auto-login 档、页面免登录直入，
+// 真实登录 UI（表单填写、提交、成功跳转、失败留页）此前零覆盖。
+// 本 spec 跑 plain 档（just dev-web <port>，不传 debug）：auto-login feature
+// 不编译进产物，#login 路由只渲染手工登录表单，无自动登录干扰。
+//
+// 前置：dev 后端 3211 在线（共享库种子 admin_dev 存在）。
+
+import { test, expect } from '@playwright/test';
+import { LoginPage } from '../pages/auth.page.js';
+const SEED_USERNAME = 'admin_dev';
+const SEED_PASSWORD = 'DevPassw0rd!12345';
+
+// 首建（dx 全图编译）可能数分钟：本 spec 的超时盖过 default 45s，
+// 跑热后实际数秒级完成，超时只在冷 target/ 时用到。
+test.setTimeout(180_000);
+test('手填 dev 种子凭据登录成功：写入登录态并回控制台', async ({ page }) => {
+  const login = new LoginPage(page, test.info().project.use.baseURL ?? 'http://127.0.0.1:8090');
+  await login.open();
+  const status = await login.fill(SEED_USERNAME, SEED_PASSWORD).then(() => login.submit());
+  expect(status, `POST /api/user/login 应 2xx，实际 ${status}`).toBeLessThan(400);
+  // 成功后 AuthPageRoot 清 hash 回控制台，access token 落持久档
+  await expect
+    .poll(() => login.storedAccessToken(), { timeout: 15_000 })
+    .not.toBeNull();
+  await expect.poll(() => login.hash(), { timeout: 15_000 }).toBe('');
+});
+
+test('错误密码：401 被拒、401 兜底踢回 #signup、无登录态', async ({ page }) => {
+  const login = new LoginPage(page, test.info().project.use.baseURL ?? 'http://127.0.0.1:8090');
+  await login.open();
+  const status = await login.fill(SEED_USERNAME, 'definitely-wrong-password').then(() =>
+    login.submit(),
+  );
+  expect(status, `错误凭据应 4xx，实际 ${status}`).toBeGreaterThanOrEqual(400);
+  // 产品行为：任意 401 触发 handle_unauthorized——清会话并 set_hash('#signup')
+  // 兜底回注册/登录页（apps/web/src/lib.rs 的 401 统一清理）。
+  await expect.poll(() => login.hash(), { timeout: 15_000 }).toBe('#signup');
+  expect(await login.storedAccessToken()).toBeNull();
+});

