+//! dioxus-motion spring 试块（临时）：复刻 VengenceUI 侧边栏"流动高亮"——
+//! 单一高亮 pill 用弹簧物理在选项间滑行（对应 framer `layoutId="sidebar-hover-bg"`
+//! spring stiffness 600 / damping 35），外加一个弹簧缩放按钮。
+//! 用途：验证 dioxus-motion 0.3.5 在 dioxus 0.7.10 web 目标下可编译、弹簧观感是否
+//! 对得上；ui-kit 正式落地此效果后删掉本文件。
+
+use dioxus::prelude::*;
+use dioxus_motion::prelude::*;
+
+/// 行高（px）：每个选项一行。
+const ROW: f32 = 44.0;
+
+/// 侧边栏高亮用弹簧（framer stiffness 600 / damping 35 1:1 参数映射）。
+const SIDEBAR_SPRING: Spring = Spring {
+    stiffness: 600.0,
+    damping: 35.0,
+    ..Spring::default()
+};
+
+/// 按钮弹簧（framer AnimatedButton stiffness 500 / damping 30 / mass 0.5）。
+const BUTTON_SPRING: Spring = Spring {
+    stiffness: 500.0,
+    damping: 30.0,
+    mass: 0.5,
+    ..Spring::default()
+};
+
+#[component]
+pub fn MotionTrial() -> Element {
+    // 高亮 pill 的 top 值：单一元素、弹簧驱动，从旧项滑到新项。
+    let mut top = use_motion(0.0f32);
+    // 按钮 scale。
+    let mut scale = use_motion(1.0f32);
+    let hovered = use_signal(|| 0usize);
+
+    // hover 切换 → pill 弹簧滑到新行。
+    use_effect(move || {
+        let i = *hovered();
+        top.animate_to(
+            i as f32 * ROW,
+            AnimationConfig::new(AnimationMode::Spring(SIDEBAR_SPRING)),
+        );
+    });
+
+    rsx! {
+        section { class: "motion-trial",
+            h3 { class: "role-title", "dioxus-motion spring 试块（临时）" }
+            p { class: "role-desc",
+                "单一高亮 pill 用弹簧在选项间滑行 = VengenceUI 侧边栏流动效果的 Dioxus 复刻"
+            }
+
+            div {
+                style: "position: relative; width: 280px; height: 176px;",
+                // 弹簧滑行的 pill（top 由 motion 驱动，绝对定位）。
+                div {
+                    style: "position: absolute; left: 4px; right: 4px; height: 44px; \
+                            border-radius: 8px; background: rgba(99,102,241,0.18); \
+                            pointer-events: none;",
+                    "top": "{*top.current()}px"
+                }
+                for i in 0..4 {
+                    button {
+                        style: "display: block; width: 100%; height: 44px; border: 0; \
+                                background: transparent; text-align: left; padding: 0 16px; \
+                                font: inherit; color: inherit; cursor: pointer;",
+                        onmouseenter: move |_| { hovered.set(i); },
+                        "选项 {i}"
+                    }
+                }
+            }
+
+            button {
+                style: "transform: scale({*scale.current()}); display: inline-block; \
+                        margin-top: 12px; padding: 8px 24px; border: 1px solid rgba(129,140,248,0.6); \
+                        border-radius: 8px; background: rgba(99,102,241,0.12); \
+                        color: inherit; font: inherit; cursor: pointer;",
+                onmouseenter: move |_| {
+                    scale.animate_to(1.05, AnimationConfig::new(AnimationMode::Spring(BUTTON_SPRING)));
+                },
+                onmouseleave: move |_| {
+                    scale.animate_to(1.0, AnimationConfig::new(AnimationMode::Spring(BUTTON_SPRING)));
+                },
+                "弹簧按钮"
+            }
+        }
+    }
+}
