+  /* 弱化文字色 —— 单色类：次要说明、占位、辅助信息。 */
+  .ui-c-muted { @apply text-muted-foreground; }
+  /* 反色文字 —— 单色类：压在强调底色上的文字。 */
+  .ui-c-on { @apply text-primary-foreground; }
+  /* 成功色 —— 单色类。 */
+  .ui-c-success { @apply text-success-foreground; }
+  /* 正文色 —— 单色类：前景色。 */
+  .ui-c-text { @apply text-foreground; }
+  /* 警告色 —— 单色类。 */
+  .ui-c-warning { @apply text-warning-foreground; }
+  /* 危险提示条 —— 破坏性操作提示：danger 底 + danger 文字。 */
+  .ui-danger-bar { @apply rounded-xl border border-destructive bg-destructive px-4 py-2 text-xs text-destructive; }
+  /* 信息条 —— 普通提示条：卡底 + 前景文字。 */
+  .ui-info-bar { @apply rounded-xl border border-border bg-card px-4 py-2 text-xs text-foreground; }
+  /* 模态遮罩 —— 全屏居中 + 半透明黑底 + 背景模糊。点遮罩关闭由调用方挂 onclick。 */
+  .ui-modal-backdrop { @apply fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm; }
+  /* 模态遮罩的顶部对齐变体 —— 对齐与上边距跟 ui-modal-backdrop 相反，
+     供「设置弹窗」这类贴顶形态使用（omenic web-ui Modal 的 top_aligned）。 */
+  .ui-modal-backdrop-top { @apply fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[14vh] backdrop-blur-sm; }
+  /* 模态内容卡 —— 居中圆角卡，最大宽度 max-w-md。 */
+  .ui-modal-card { @apply w-full max-w-md rounded-2xl border border-border bg-card p-5 shadow-xl; }
+  /* 模态标题行 —— 左标题 + 右关闭按钮的两端布局。 */
+  .ui-modal-header { @apply mb-5 flex items-center justify-between; }
+  /* 页面底 —— 铺满一屏的页面容器：最小高度撑满 + 背景/前景色。应用级根容器用它。 */
+  .ui-page-bg { @apply relative min-h-screen overflow-x-hidden bg-background text-foreground; }
+  /* 区块外壳 —— 最常用的容器：圆角 + 描边 + 卡底色 + p-6。页面区段、设置分组、弹窗内容都用它。 */
+  .ui-section { @apply rounded-xl border border-border bg-card p-6; }
+  /* 区块标题行 —— 纯布局：mb-4 + flex 两端对齐，不含视觉，与主题无关。 */
+  .ui-section-header { @apply mb-4 flex items-center justify-between; }
+  /* 区块外壳（可滚动） —— 与 ui-section 同壳，额外 scroll-mt-8 —— 锚点跳转时不被吸顶栏遮住。 */
+  .ui-section-scroll { @apply scroll-mt-8 rounded-xl border border-border bg-card p-6; }
+  /* 区块标题文字 —— 中等字号 + medium 字重 + 前景色。 */
+  .ui-section-title { @apply text-lg font-medium text-foreground; }
+  /* 状态胶囊 —— 药丸形小徽标：次级底 + 弱化文字。文案走占位，不写死在样式里。 */
+  .ui-status-pill { @apply rounded-full bg-secondary px-3 py-1 text-xs text-muted-foreground; }
+  /* 危险底色 —— 单色类。 */
+  .ui-s-danger { @apply bg-destructive; }
+  /* 强调面底色 —— 单色类。 */
+  .ui-s-on { @apply bg-primary; }
+  /* 面板底色 —— 单色类：表面填充。 */
+  .ui-s-panel { @apply bg-card; }
+  /* 抬升面底色 —— 单色类：浮在面板之上的层。 */
+  .ui-s-raised { @apply bg-secondary; }
+  /* 成功底色 —— 单色类。 */
+  .ui-s-success { @apply bg-success; }
+  /* 警告底色 —— 单色类。 */
+  .ui-s-warning { @apply bg-warning; }
+  /* 激活标签 —— 前景色用 --primary-foreground，配合 z-10 压在指示条之上。 */
+  .ui-tab-active { @apply relative z-10 flex-1 rounded-full px-3.5 py-1.5 text-xs font-medium transition-colors duration-200 text-primary-foreground; }
+  /* 标签指示条 —— 绝对定位滑块，宽度一半（w-1/2），靠 transform 在标签间平移。动效时长调这里。 */
+  .ui-tab-indicator { @apply absolute inset-y-0 w-1/2 rounded-full bg-primary transition-transform duration-200; }
+  /* 标签页外壳 —— 容器圆角胶囊 + 内部 p-1 留白；激活/未激活子态由 ui-tab-active / ui-tab-inactive 承担。 */
+  .ui-tab-switcher { @apply relative mb-6 flex rounded-full border border-border bg-card p-1; }
+  /* 正文文字 —— 同上，与 .role-body 重复。 */
+  .ui-type-body { @apply text-sm text-foreground; }
+  /* 按钮文字 —— 同上，与 .role-button 重复。 */
+  .ui-type-button { @apply text-sm font-medium; }
+  /* 卡片标题文字 —— 同上，与 .role-card 重复。 */
+  .ui-type-card-title { @apply text-sm font-medium text-foreground; }
+  /* 说明文字 —— 同上，与 .role-desc 重复。 */
+  .ui-type-desc { @apply text-xs text-muted-foreground; }
+  /* 字段标签文字 —— 同上，与 .role-label 重复。 */
+  .ui-type-label { @apply text-[11px] font-medium text-muted-foreground; }
+  /* 标题文字 —— **与 tokens.css 的 .role-title 语义重复**，见文首「已知遗留」。 */
+  .ui-type-title { @apply text-lg font-bold text-foreground; }
+  /* 数值文字 —— 同上，与 .role-value 重复。 */
+  .ui-type-value { @apply text-2xl font-semibold text-foreground; }
+}
