@@ -0,0 +1,239 @@
+//! Configurable keymap for the snippets panel.
+//!
+//! Reads `keymap.toml` from the snippets config dir (same place as
+//! `default_root()`; overridable via `DESKCTL_KEYMAP_CONF`). Missing file →
+//! built-in defaults. Unlisted actions fall back to defaults, so a config
+//! only needs to touch the keys it wants to change.
+//!
+//! ```toml
+//! # ~/.config/deskctl/snippets/keymap.toml
+//! tab_left   = ["[", "left"]
+//! tab_right  = ["]", "right"]
+//! template_up = ["up"]
+//! template_down = ["down"]
+//! copy       = ["enter", "space"]
+//! quit       = ["esc", "q"]
+//! clear_search = ["ctrl-c", "esc"]
+//! search_backspace = ["backspace", "ctrl-h"]
+//! ```
+//!
+//! Key tokens: arrow/function `left right up down enter space esc backspace
+//! tab home end pageup pagedown delete insert`, a single printable char
+//! (`"["`, `"]"`, `"q"`), or `ctrl-<char>` for control chords.
+
+use anyhow::{Context, Result};
+use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
+use serde::Deserialize;
+use std::path::Path;
+
+/// All keybindings for the snippets panel, as normalized `KeyEvent`s.
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub struct Keymap {
+    pub tab_left: Vec<KeyEvent>,
+    pub tab_right: Vec<KeyEvent>,
+    pub template_up: Vec<KeyEvent>,
+    pub template_down: Vec<KeyEvent>,
+    pub copy: Vec<KeyEvent>,
+    pub quit: Vec<KeyEvent>,
+    pub clear_search: Vec<KeyEvent>,
+    pub search_backspace: Vec<KeyEvent>,
+}
+
+impl Keymap {
+    /// Load from `path`, falling back to defaults for a missing file or
+    /// any action not present in the file.
+    pub fn load(path: &Path) -> Result<Self> {
+        if !path.exists() {
+            return Ok(Self::default());
+        }
+        let text =
+            std::fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
+        let raw: Raw =
+            toml::from_str(&text).with_context(|| format!("parse {}", path.display()))?;
+        Ok(Self {
+            tab_left: merge(raw.tab_left, &["[", "left"])?,
+            tab_right: merge(raw.tab_right, &["]", "right"])?,
+            template_up: merge(raw.template_up, &["up"])?,
+            template_down: merge(raw.template_down, &["down"])?,
+            copy: merge(raw.copy, &["enter", "space"])?,
+            quit: merge(raw.quit, &["esc", "q"])?,
+            clear_search: merge(raw.clear_search, &["ctrl-c", "esc"])?,
+            search_backspace: merge(raw.search_backspace, &["backspace", "ctrl-h"])?,
+        })
+    }
+}
+
+impl Default for Keymap {
+    fn default() -> Self {
+        Self {
+            tab_left: keys(&["[", "left"]),
+            tab_right: keys(&["]", "right"]),
+            template_up: keys(&["up"]),
+            template_down: keys(&["down"]),
+            copy: keys(&["enter", "space"]),
+            quit: keys(&["esc", "q"]),
+            clear_search: keys(&["ctrl-c", "esc"]),
+            search_backspace: keys(&["backspace", "ctrl-h"]),
+        }
+    }
+}
+
+#[derive(Default, Deserialize)]
+struct Raw {
+    tab_left: Option<Vec<String>>,
+    tab_right: Option<Vec<String>>,
+    template_up: Option<Vec<String>>,
+    template_down: Option<Vec<String>>,
+    copy: Option<Vec<String>>,
+    quit: Option<Vec<String>>,
+    clear_search: Option<Vec<String>>,
+    search_backspace: Option<Vec<String>>,
+}
+
+fn merge(list: Option<Vec<String>>, defaults: &[&str]) -> Result<Vec<KeyEvent>> {
+    match list {
+        Some(tokens) => tokens.iter().map(|t| parse(t)).collect(),
+        None => Ok(keys(defaults)),
+    }
+}
+
+fn keys(tokens: &[&str]) -> Vec<KeyEvent> {
+    tokens
+        .iter()
+        .map(|t| parse(t).expect("built-in key token is valid"))
+        .collect()
+}
+
+/// Parse a key token into a `KeyEvent`.
+pub fn parse(token: &str) -> Result<KeyEvent> {
+    let (modifiers, name) = match token
+        .strip_prefix("ctrl-")
+        .or_else(|| token.strip_prefix("ctrl_"))
+    {
+        Some(rest) => (KeyModifiers::CONTROL, rest),
+        None => (KeyModifiers::NONE, token),
+    };
+    let code = match name {
+        "left" => KeyCode::Left,
+        "right" => KeyCode::Right,
+        "up" => KeyCode::Up,
+        "down" => KeyCode::Down,
+        "enter" | "return" => KeyCode::Enter,
+        "space" => KeyCode::Char(' '),
+        "esc" | "escape" => KeyCode::Esc,
+        "backspace" => KeyCode::Backspace,
+        "tab" => KeyCode::Tab,
+        "backtab" => KeyCode::BackTab,
+        "home" => KeyCode::Home,
+        "end" => KeyCode::End,
+        "pageup" => KeyCode::PageUp,
+        "pagedown" => KeyCode::PageDown,
+        "delete" | "del" => KeyCode::Delete,
+        "insert" => KeyCode::Insert,
+        single if single.chars().count() == 1 => {
+            KeyCode::Char(single.chars().next().expect("one char"))
+        }
+        other if other.starts_with('f') && other.len() <= 3 => {
+            let n: u8 = other[1..]
+                .parse()
+                .map_err(|_| anyhow::anyhow!("unknown key token: {other:?}"))?;
+            if (1..=12).contains(&n) {
+                KeyCode::F(n)
+            } else {
+                anyhow::bail!("unknown key token: {other:?}")
+            }
+        }
+        other => anyhow::bail!("unknown key token: {other:?}"),
+    };
+    Ok(KeyEvent::new(code, modifiers))
+}
+
+/// Subsequence fuzzy match (case-sensitive inputs): every `query` char must
+/// appear in `name` in order. Empty query matches everything.
+pub fn fuzzy(name: &str, query: &str) -> bool {
+    let mut rest = name.chars();
+    for target in query.chars() {
+        match rest.find(|c| *c == target) {
+            Some(_) => {}
+            None => return false,
+        }
+    }
+    true
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn default_keymap_has_brackets_and_no_hjkl() {
+        let km = Keymap::default();
+        assert!(km
+            .tab_left
+            .contains(&KeyEvent::new(KeyCode::Char('['), KeyModifiers::NONE)));
+        assert!(km
+            .tab_right
+            .contains(&KeyEvent::new(KeyCode::Char(']'), KeyModifiers::NONE)));
+        assert!(!km.tab_left.iter().any(|k| k.code == KeyCode::Char('h')));
+        assert!(!km.template_up.iter().any(|k| k.code == KeyCode::Char('k')));
+        assert!(km
+            .clear_search
+            .contains(&KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL)));
+        assert!(km
+            .search_backspace
+            .contains(&KeyEvent::new(KeyCode::Char('h'), KeyModifiers::CONTROL)));
+    }
+
+    #[test]
+    fn load_missing_file_returns_defaults() {
+        let km = Keymap::load(Path::new("/nonexistent/keymap.toml")).expect("load");
+        assert_eq!(km, Keymap::default());
+    }
+
+    #[test]
+    fn load_merges_partial_config() {
+        let dir = std::env::temp_dir().join(format!("deskctl-keymap-{}", std::process::id()));
+        std::fs::create_dir_all(&dir).expect("dir");
+        let path = dir.join("keymap.toml");
+        std::fs::write(&path, "copy = [\"y\"]\n").expect("write");
+        let km = Keymap::load(&path).expect("load");
+        // overridden
+        assert!(km
+            .copy
+            .contains(&KeyEvent::new(KeyCode::Char('y'), KeyModifiers::NONE)));
+        assert!(!km
+            .copy
