+    let mut td = Tdigest::new(50.0);
+    for &v in &vals {
+        td.add(v);
+    }
+    let q90 = td.quantile(0.9).unwrap();
+    let q100 = td.quantile(1.0).unwrap();
+    assert!(q90 <= q100, "q90={q90} > q100={q100}");
+    assert_eq!(q90, q100, "frac=1.0 必须精确落在末质心均值上");
